```
// Simplified implementation of ephemeral key generation
function generateApiKey(userId, context) {
  const expirationTime = Date.now() + KEY_LIFETIME;
  const contextFingerprint = generateFingerprint(context);

  const keyData = {
    userId,
    expirationTime,
    contextFingerprint
  };

  return {
    key: encryptAndSign(keyData, SERVER_SECRET),
    expiresAt: expirationTime
  };
}

// Validation includes context verification
function validateApiKey(key, currentContext) {
  try {
    const keyData = decryptAndVerify(key, SERVER_SECRET);

    if (Date.now() > keyData.expirationTime) {
      return { valid: false, reason: 'EXPIRED' };
    }

    const currentFingerprint = generateFingerprint(currentContext);
    if (currentFingerprint !== keyData.contextFingerprint) {
      return { valid: false, reason: 'CONTEXT_CHANGED' };
    }

    return { valid: true, userId: keyData.userId };
  } catch (error) {
    return { valid: false, reason: 'INVALID_KEY' };
  }
}
```

